-- Russia 1918: unique units and buildings of the six sides, cloned from the stock rows at load time, and the abilities whose
-- stock effects are dead in the scenario (generated by text/build_text.py from text/uniques.py).
-- The donor civilizations' own uniques are unhooked; stock 3D models, icons, techs and upgrade paths are kept.

-- Tachanka (RED): UNIT_GATLINGGUN
CREATE TEMP TABLE tmp_u AS SELECT * FROM Units WHERE Type = 'UNIT_GATLINGGUN';
UPDATE tmp_u SET ID = (SELECT MAX(ID) + 1 FROM Units), Type = 'UNIT_RUS1918_TACHANKA', Description = 'TXT_KEY_UNIT_RUS1918_TACHANKA', Civilopedia = 'TXT_KEY_CIV5_RUS1918_TACHANKA_TEXT', Strategy = 'TXT_KEY_UNIT_RUS1918_TACHANKA_STRATEGY', Help = 'TXT_KEY_UNIT_RUS1918_TACHANKA_HELP', Moves = 3;

